// @ts-ignore TS7016: JS module without types
import { apiURL } from "../api-base.js";
// Use only complete, exact-window API responses. Preserve the static dataset
// as a visibly labelled fallback; never mix the two calculations in one table.
export async function compareLive(ids, startMs, hours, fetcher = fetch) {
    if (!ids.length || ids.length > 3 || new Set(ids).size !== ids.length || !Number.isInteger(hours) || hours < 1 || hours > 720)
        return null;
    const start = new Date(startMs).toISOString();
    try {
        const response = await fetcher(apiURL("/api/compare"), { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ site_ids: ids, start_utc: start, duration_hours: hours }), signal: AbortSignal.timeout(8000), redirect: "error" });
        if (!response.ok)
            return null;
        const body = await response.json();
        if (!Array.isArray(body?.results) || body.results.length !== ids.length || typeof body.request_sha256 !== "string")
            return null;
        const entries = new Map();
        for (const r of body.results) {
            const m = r.evaluation?.metrics, id = r.site?.id;
            if (id === undefined || !ids.includes(id) || entries.has(id) || r.data_status !== "AVAILABLE" || !m || !String(r.science_status).startsWith("PRELIMINARY") ||
                Date.parse(r.evaluation.start_utc) !== startMs || Date.parse(r.evaluation.end_utc) !== startMs + hours * 3600000 ||
                ![m.sun_visible_fraction, m.earth_visible_fraction, m.simultaneous_fraction].every(x => Number.isFinite(x) && x >= 0 && x <= 1) ||
                ![m.longest_continuous_dark_hours, m.longest_continuous_comm_gap_hours].every(x => Number.isFinite(x) && x >= 0 && x <= hours))
                return null;
            entries.set(id, { status: "COMPUTED", sunPct: m.sun_visible_fraction * 100, earthPct: m.earth_visible_fraction * 100, bothPct: m.simultaneous_fraction * 100,
                longestDarkH: m.longest_continuous_dark_hours, longestBlackoutH: m.longest_continuous_comm_gap_hours,
                origin: "POST /api/compare", science_status: r.science_status, series_sha256: r.site.series_sha256 || null, provenance: r.provenance || null, request_sha256: body.request_sha256 });
        }
        return entries;
    }
    catch {
        return null;
    }
}
